    '<span onclick="event.stopPropagation();_jspVaihda(1)" title="Terveyssyy — katso Terveys/Mittaus-välilehti (syytä ei kirjata tähän, GDPR)" style="cursor:pointer;font-size:11px">🩹</span>': '<span onclick="event.stopPropagation();_jspVaihda(1)" title="Hälsoorsak — se Hälsa/Mätning-fliken (orsaken registreras inte här, GDPR)" style="cursor:pointer;font-size:11px">🩹</span>',
    '<div style="font-size:10px;font-weight:600;letter-spacing:.16em;text-transform:uppercase;color:var(--teal);margin-bottom:3px">🎯 Tavoitejakauma · sessiot → IDP</div>': '<div style="font-size:10px;font-weight:600;letter-spacing:.16em;text-transform:uppercase;color:var(--teal);margin-bottom:3px">🎯 Målfördelning · sessioner → IDP</div>',
    '<div style="font-size:10.5px;color:var(--ink3);font-family:var(--font-mono);margin-bottom:9px">Kukin sessio kertyy jaksofokuksen tavoitteelle · koostuu automaattisesti</div>': '<div style="font-size:10.5px;color:var(--ink3);font-family:var(--font-mono);margin-bottom:9px">Varje session ackumuleras till periodfokusets mål · sammanställs automatiskt</div>',
    'tällä vk': 'denna v',
    '<div style="font-size:10.5px;color:var(--ink3);margin-top:8px">Seuraava IDP-katselmus: jakson lopussa (': '<div style="font-size:10.5px;color:var(--ink3);margin-top:8px">Nästa IDP-genomgång: vid periodens slut (',
    'vk) — <span onclick="event.stopPropagation();_jspVaihda(3)" style="color:var(--teal);cursor:pointer;font-weight:600">avaa Kehitys →</span></div>': 'vk) — <span onclick="event.stopPropagation();_jspVaihda(3)" style="color:var(--teal);cursor:pointer;font-weight:600">öppna Utveckling →</span></div>',
    '<span style="font-size:10px;font-weight:600;letter-spacing:.16em;text-transform:uppercase;color:var(--ink2)">📊 Kuorma · sRPE (rpe × min)</span>': '<span style="font-size:10px;font-weight:600;letter-spacing:.16em;text-transform:uppercase;color:var(--ink2)">📊 Belastning · sRPE (rpe × min)</span>',
    '<span style="font-family:var(--font-mono);font-size:10.5px;color:var(--ink3)">viikko': '<span style="font-family:var(--font-mono);font-size:10.5px;color:var(--ink3)">vecka',
    '<div style="font-size:9.5px;color:var(--ink3);margin-top:6px">▨ katkoviiva = suunniteltu · täysi = toteutunut · ACWR suuntaa-antava (ei absoluuttinen totuus)</div>': '<div style="font-size:9.5px;color:var(--ink3);margin-top:6px">▨ streckad = planerad · heldragen = genomförd · ACWR vägledande (inte absolut sanning)</div>',
